def largest_prime_factor(n: int) -> int:
    largest = 2
    factor = 2
    while n % factor == 0:
        n //= factor
        largest = factor
    factor = 3
    while factor * factor <= n:
        while n % factor == 0:
            n //= factor
            largest = factor
        factor += 2
    if n > 1:
        largest = n
    return largest
